import{_ as i,o as s,c as t,ag as e}from"./chunks/framework.-Wrcbzkw.js";const k=JSON.parse('{"title":"D2C 结构转换 Agent 设计","description":"","frontmatter":{},"headers":[],"relativePath":"project/D2C/结构转换Agent设计.md","filePath":"project/D2C/结构转换Agent设计.md","lastUpdated":1781077191000}'),l={name:"project/D2C/结构转换Agent设计.md"};function n(p,a,d,h,o,r){return s(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="d2c-结构转换-agent-设计" tabindex="-1">D2C 结构转换 Agent 设计 <a class="header-anchor" href="#d2c-结构转换-agent-设计" aria-label="Permalink to &quot;D2C 结构转换 Agent 设计&quot;">​</a></h1><p>结构转换 Agent 是 D2C 流水线的第二个阶段。它接收清洗后的 Figma 节点数据，将设计工具中的节点、布局和样式转换为统一的组件 DSL（Domain-Specific Language，领域专用语言）。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>清洗后的 Figma 数据 -&gt; 结构转换 Agent -&gt; 组件 DSL</span></span></code></pre></div><h2 id="一、为什么清洗后的数据还不能直接生成代码" tabindex="-1">一、为什么清洗后的数据还不能直接生成代码 <a class="header-anchor" href="#一、为什么清洗后的数据还不能直接生成代码" aria-label="Permalink to &quot;一、为什么清洗后的数据还不能直接生成代码&quot;">​</a></h2><p>数据清洗解决的是冗余问题，但清洗后的数据仍然使用 Figma 的表达方式。例如：</p><ul><li><code>FRAME</code> 表示容器，但不明确它应该生成页面、区块还是普通 <code>div</code></li><li><code>TEXT</code> 只表示文本节点，不包含业务组件语义</li><li>自动布局描述的是设计工具行为，不完全等同于 CSS</li><li>组件实例可能带有复杂的引用和覆盖关系</li></ul><p>如果让代码生成模型直接理解这些节点，每次生成都需要重新完成“设计节点到前端组件”的推断，结果容易不一致。</p><h2 id="二、为什么需要-dsl" tabindex="-1">二、为什么需要 DSL <a class="header-anchor" href="#二、为什么需要-dsl" aria-label="Permalink to &quot;二、为什么需要 DSL&quot;">​</a></h2><p>DSL 是设计数据和前端代码之间的稳定中间层。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Figma 节点 -&gt; 组件 DSL -&gt; React / Vue / HTML</span></span></code></pre></div><p>它将不同框架共有的信息提取出来，例如：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Button&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;props&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;variant&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;primary&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;text&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;提交&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;layout&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;width&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">120</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;height&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">40</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>有了 DSL，同一份设计结构可以生成 React、Vue 或其他目标代码，而不需要重复解析 Figma。</p><h2 id="三、结构转换-agent-的设计目标" tabindex="-1">三、结构转换 Agent 的设计目标 <a class="header-anchor" href="#三、结构转换-agent-的设计目标" aria-label="Permalink to &quot;三、结构转换 Agent 的设计目标&quot;">​</a></h2><ol><li>将 Figma 节点映射为前端组件概念</li><li>还原父子关系和页面层级</li><li>将自动布局转换为通用布局描述</li><li>提取组件属性、文本内容和视觉样式</li><li>为知识检索和代码生成提供稳定输入</li></ol><p>常见映射关系如下：</p><table tabindex="0"><thead><tr><th>Figma 节点</th><th>DSL 组件</th></tr></thead><tbody><tr><td><code>FRAME</code></td><td><code>Page</code>、<code>Container</code>、<code>Section</code></td></tr><tr><td><code>TEXT</code></td><td><code>Text</code>、<code>Heading</code>、<code>Label</code></td></tr><tr><td><code>RECTANGLE</code></td><td><code>Box</code>、<code>Image</code>、<code>Divider</code></td></tr><tr><td><code>COMPONENT</code> / <code>INSTANCE</code></td><td>可复用业务组件</td></tr></tbody></table><h2 id="四、为什么单独设计这一阶段" tabindex="-1">四、为什么单独设计这一阶段 <a class="header-anchor" href="#四、为什么单独设计这一阶段" aria-label="Permalink to &quot;四、为什么单独设计这一阶段&quot;">​</a></h2><p>结构转换本质上是确定性的语义归一化。如果把它合并进代码生成阶段：</p><ul><li>模型每次都需要重新理解 Figma 节点</li><li>React 和 Vue 的生成逻辑会重复处理相同结构</li><li>很难检查错误究竟来自设计解析还是代码生成</li><li>无法方便地替换代码生成模型</li></ul><p>独立 DSL 让每个阶段职责清晰，也让中间结果可以被测试、缓存和人工检查。</p><h2 id="五、为什么优先使用规则引擎" tabindex="-1">五、为什么优先使用规则引擎 <a class="header-anchor" href="#五、为什么优先使用规则引擎" aria-label="Permalink to &quot;五、为什么优先使用规则引擎&quot;">​</a></h2><p>节点映射、布局换算和树结构转换存在大量明确规则，使用普通程序更稳定：</p><ul><li>相同节点始终得到相同 DSL</li><li>转换规则容易单元测试</li><li>不产生额外模型调用成本</li><li>出错时可以定位到具体节点和规则</li><li>不会因为提示词变化导致结构漂移</li></ul><p>对于难以通过规则识别的业务语义，可以后续增加模型分类，但不应让大模型替代所有基础转换。</p><h2 id="六、失败风险与验证方式" tabindex="-1">六、失败风险与验证方式 <a class="header-anchor" href="#六、失败风险与验证方式" aria-label="Permalink to &quot;六、失败风险与验证方式&quot;">​</a></h2><p>常见失败包括：</p><ul><li>错误识别容器和组件</li><li>丢失节点层级</li><li>将横向布局转换为纵向布局</li><li>忽略组件实例的属性覆盖</li><li>过度使用绝对定位</li></ul><p>可以通过 DSL Schema 校验、节点数量对比、布局快照和典型组件测试集验证转换质量。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>结构转换 Agent 的作用，是将 Figma 的设计工具语言转换为前端系统能够稳定理解的组件语言。它隔离了设计数据与目标框架，使后续知识检索和代码生成不必反复处理复杂的 Figma 原始结构。</p>`,31)])])}const g=i(l,[["render",n]]);export{k as __pageData,g as default};
